const a = finderAnswers.value;
const smallTeam = ["1\u201310", "11\u201350"].includes(a.company_size);
const smallBudget = ["Under \u20b92L", "\u20b92L\u2013\u20b910L"].includes(a.budget);
const immediate = a.timeline === "Immediately";
const standard = ["New ERP Implementation", "Replace Existing ERP"].includes(a.looking_for);
const qualifies = smallTeam && smallBudget && immediate && standard;
finderOutcome.value = qualifies ? 'starter' : 'matches';
call('connect.api.customer.save_customer_requirement', {
  country: a.country, industry: a.industry,
  apps: JSON.stringify(a.apps || []),
  looking_for: a.looking_for, company_size: a.company_size,
  current_situation: a.current_situation, timeline: a.timeline,
  delivery_preference: a.delivery_preference, budget: a.budget,
  special_requirements: JSON.stringify(a.requirements || []), additional_notes: a.additional_notes,
  outcome: qualifies ? 'Starter Pack' : 'Matches',
}).then(() => {
  if (myRequirement && myRequirement.reload) { myRequirement.reload(); }
  toast({ title: 'Saved', text: 'Your requirements have been saved.', icon: 'check' });
}).catch(() => {
  toast({ title: 'Not saved', text: 'Log in to save your requirements for later.', icon: 'alert-circle' });
});
call('connect.api.partner.list_matching_partners', { answers: JSON.stringify(a) }).then((r) => {
  wizardMatches.value = r || [];
  try { localStorage.setItem('connect_wizard_results', JSON.stringify({ answers: a, matches: r || [] })); } catch (e) {}
});
finderOpen.value = false;

